public static int upgradeRange(int defaultRange, World world, BlockPos pos) {
        int newRange = defaultRange;
        for (int i = 0; i < 3; i++) {
            Block block = world.getBlockState(pos.up(1 + i)).getBlock();
            if (block == InitBlocks.blockPhantomBooster) {
                newRange = newRange * 2;
            } else {
                break;
            }
        }
        return newRange;
    }

